using System.Globalization;
using System.Text;

namespace Barbican.GenTokens;

/// <summary>Writes the generated files. Output is deterministic and uses \n line endings.</summary>
public static class Emitters
{
    public const string SourcePath = "design/legacy-slint/theme.slint";
    public const string TokensXamlPath = "src/Barbican.App/Themes/Tokens.xaml";
    public const string ShapeBentoXamlPath = "src/Barbican.App/Themes/Shape.Bento.xaml";
    public const string ShapeNordicXamlPath = "src/Barbican.App/Themes/Shape.Nordic.xaml";
    public const string TokensCsPath = "src/Barbican.Presentation/Theme/Tokens.g.cs";

    private const string XamlNs = "http://schemas.microsoft.com/winfx/2006/xaml/presentation";
    private const string XNs = "http://schemas.microsoft.com/winfx/2006/xaml";

    /// <summary>All generated files: repo-relative path → content.</summary>
    public static IReadOnlyDictionary<string, string> All(TokenSet tokens) => new Dictionary<string, string>(StringComparer.Ordinal)
    {
        [TokensXamlPath] = TokensXaml(tokens),
        [ShapeBentoXamlPath] = ShapeXaml(tokens, nordic: false),
        [ShapeNordicXamlPath] = ShapeXaml(tokens, nordic: true),
        [TokensCsPath] = TokensCs(tokens),
    };

    public static string TokensXaml(TokenSet tokens)
    {
        ArgumentNullException.ThrowIfNull(tokens);
        var sb = new StringBuilder();
        sb.Append("<?xml version=\"1.0\" encoding=\"utf-8\"?>\n");
        sb.Append("<!--\n");
        sb.Append(CultureInfo.InvariantCulture, $"  Generated by tools/Barbican.GenTokens from {SourcePath}. Do not edit: run tools/build.ps1 gen-tokens.\n");
        sb.Append("  Palette brushes start at the default variant (dark, normal contrast, Bulwark). Theme, contrast and\n");
        sb.Append("  style switches rewrite each brush's Color in place from Barbican.Presentation.Theme.Tokens.Palette\n");
        sb.Append("  (PORT-PLAN.md §3.7), so nothing is re-templated and nothing flashes.\n");
        sb.Append("-->\n");
        sb.Append(CultureInfo.InvariantCulture, $"<ResourceDictionary xmlns=\"{XamlNs}\" xmlns:x=\"{XNs}\">\n");
        sb.Append("  <!-- Palette -->\n");
        var defaults = tokens.Palettes[8];
        foreach (var key in tokens.ColorKeys)
        {
            sb.Append(CultureInfo.InvariantCulture, $"  <SolidColorBrush x:Key=\"{key}\" Color=\"{new ColorValue(defaults[key]).ToXaml()}\" />\n");
        }

        sb.Append("  <!-- Motion (values with motion on; reduce motion sets durations to 0 at runtime) -->\n");
        foreach (var (key, value, _) in tokens.Motion)
        {
            sb.Append(CultureInfo.InvariantCulture, $"  <x:Double x:Key=\"Motion.{key}\">{TokenSet.Num(value)}</x:Double>\n");
        }

        sb.Append("</ResourceDictionary>\n");
        return sb.ToString();
    }

    public static string ShapeXaml(TokenSet tokens, bool nordic)
    {
        ArgumentNullException.ThrowIfNull(tokens);
        var values = nordic ? tokens.ShapeNordic : tokens.ShapeBento;
        var sb = new StringBuilder();
        sb.Append("<?xml version=\"1.0\" encoding=\"utf-8\"?>\n");
        sb.Append("<!--\n");
        sb.Append(CultureInfo.InvariantCulture, $"  Generated by tools/Barbican.GenTokens from {SourcePath}. Do not edit: run tools/build.ps1 gen-tokens.\n");
        sb.Append(CultureInfo.InvariantCulture, $"  Shape and type-scale tokens for the {(nordic ? "Nordic" : "Bento")} style, in px. One of the two Shape.*.xaml\n");
        sb.Append("  dictionaries is merged once, when the style is chosen (PORT-PLAN.md §3.7).\n");
        sb.Append("-->\n");
        sb.Append(CultureInfo.InvariantCulture, $"<ResourceDictionary xmlns=\"{XamlNs}\" xmlns:x=\"{XNs}\">\n");
        foreach (var key in tokens.ShapeKeys)
        {
            sb.Append(CultureInfo.InvariantCulture, $"  <x:Double x:Key=\"Shape.{key}\">{TokenSet.Num(values[key])}</x:Double>\n");
        }

        sb.Append("</ResourceDictionary>\n");
        return sb.ToString();
    }

    public static string TokensCs(TokenSet tokens)
    {
        ArgumentNullException.ThrowIfNull(tokens);
        var sb = new StringBuilder();
        sb.Append("// <auto-generated>\n");
        sb.Append(CultureInfo.InvariantCulture, $"//   Generated by tools/Barbican.GenTokens from {SourcePath} (the Rust app's ui/theme.slint).\n");
        sb.Append("//   Do not edit: change the source or the generator and run tools/build.ps1 gen-tokens.\n");
        sb.Append("// </auto-generated>\n");
        sb.Append("#nullable enable\n");
        sb.Append("using System.Collections.Frozen;\n\n");
        sb.Append("namespace Barbican.Presentation.Theme;\n\n");
        sb.Append("/// <summary>Design tokens from theme.slint: palette per variant, shape per style, motion, easing, icons.</summary>\n");
        sb.Append("public static partial class Tokens\n{\n");

        sb.Append("    /// <summary>Palette keys (XAML brush keys), in theme.slint order.</summary>\n");
        sb.Append("    public static IReadOnlyList<string> ColorKeys { get; } =\n    [\n");
        foreach (var key in tokens.ColorKeys)
        {
            sb.Append(CultureInfo.InvariantCulture, $"        \"{key}\",\n");
        }

        sb.Append("    ];\n\n");
        AppendPalettes(sb, tokens);
        AppendShapes(sb, tokens);
        AppendMotion(sb, tokens);
        sb.Append("}\n");
        return sb.ToString();
    }

    private static void AppendPalettes(StringBuilder sb, TokenSet tokens)
    {
        sb.Append("    // One palette per ThemeVariant.Index: key -> 0xAARRGGBB.\n");
        sb.Append("    private static readonly FrozenDictionary<string, uint>[] Palettes =\n    [\n");
        for (var i = 0; i < tokens.Palettes.Count; i++)
        {
            sb.Append(CultureInfo.InvariantCulture, $"        // {(i < Variant.All.Count ? Variant.All[i].ToString() : $"bulwark-{i - 8}")}\n");
            sb.Append("        new Dictionary<string, uint>(StringComparer.Ordinal)\n        {\n");
            foreach (var key in tokens.ColorKeys)
            {
                sb.Append(CultureInfo.InvariantCulture, $"            [\"{key}\"] = 0x{tokens.Palettes[i][key]:X8},\n");
            }

            sb.Append("        }.ToFrozenDictionary(StringComparer.Ordinal),\n");
        }

        sb.Append("    ];\n\n");
        sb.Append("    /// <summary>The palette of one variant: key -> 0xAARRGGBB.</summary>\n");
        sb.Append("    public static IReadOnlyDictionary<string, uint> Palette(ThemeVariant variant) => Palettes[variant.Index];\n\n");
    }

    private static void AppendShapes(StringBuilder sb, TokenSet tokens)
    {
        sb.Append("    /// <summary>Shape and type-scale keys (XAML keys are \"Shape.\" + key), in theme.slint order.</summary>\n");
        sb.Append("    public static IReadOnlyList<string> ShapeKeys { get; } =\n    [\n");
        foreach (var key in tokens.ShapeKeys)
        {
            sb.Append(CultureInfo.InvariantCulture, $"        \"{key}\",\n");
        }

        sb.Append("    ];\n\n");
        AppendShape(sb, "ShapeBento", tokens.ShapeKeys, tokens.ShapeBento);
        AppendShape(sb, "ShapeNordic", tokens.ShapeKeys, tokens.ShapeNordic);
        sb.Append("    /// <summary>Shape tokens of a style, in px.</summary>\n");
        sb.Append("    public static IReadOnlyDictionary<string, double> Shape(bool nordic) => nordic ? ShapeNordic : ShapeBento;\n\n");
    }

    private static void AppendMotion(StringBuilder sb, TokenSet tokens)
    {
        sb.Append("    /// <summary>Motion tokens (design/MOTION.md) with motion on. Reduce motion makes every duration 0 and\n");
        sb.Append("    /// PopScale 1 and RisePx 0; rapid selection makes List and Late 0. The app applies both at runtime.</summary>\n");
        sb.Append("    public static class Motion\n    {\n");
        foreach (var (key, value, unit) in tokens.Motion)
        {
            sb.Append(CultureInfo.InvariantCulture, $"        public const double {key}{unit} = {TokenSet.Num(value)};\n");
        }

        sb.Append("    }\n\n");

        sb.Append("    /// <summary>Easing curves as cubic-bezier control points (XAML KeySpline: (X1,Y1) (X2,Y2)).</summary>\n");
        sb.Append("    public static class Ease\n    {\n");
        foreach (var (key, c) in tokens.Ease)
        {
            sb.Append(CultureInfo.InvariantCulture, $"        public static (double X1, double Y1, double X2, double Y2) {key} => ({TokenSet.Num(c.X1)}, {TokenSet.Num(c.Y1)}, {TokenSet.Num(c.X2)}, {TokenSet.Num(c.Y2)});\n");
        }

        sb.Append("    }\n\n");

        sb.Append("    /// <summary>Line icons from the mockups: SVG path data in a 24 x 24 box, stroked (not filled).</summary>\n");
        sb.Append("    public static IReadOnlyDictionary<string, string> Icons { get; } = new Dictionary<string, string>(StringComparer.Ordinal)\n    {\n");
        foreach (var (key, path) in tokens.Icons)
        {
            sb.Append(CultureInfo.InvariantCulture, $"        [\"{key}\"] = \"{path}\",\n");
        }

        sb.Append("    }.ToFrozenDictionary(StringComparer.Ordinal);\n");
    }

    private static void AppendShape(StringBuilder sb, string name, IReadOnlyList<string> keys, IReadOnlyDictionary<string, double> values)
    {
        sb.Append(CultureInfo.InvariantCulture, $"    private static readonly FrozenDictionary<string, double> {name} = new Dictionary<string, double>(StringComparer.Ordinal)\n    {{\n");
        foreach (var key in keys)
        {
            sb.Append(CultureInfo.InvariantCulture, $"        [\"{key}\"] = {TokenSet.Num(values[key])},\n");
        }

        sb.Append("    }.ToFrozenDictionary(StringComparer.Ordinal);\n\n");
    }
}
